def accepted(mod,ordinary):
 code=mod['code'];mode=mod['mode'];ranges={'dmg-fire','dmg-ltng','dmg-cold','dmg-pois'};parameter=code.endswith('/lvl') or code in {'rep-dur','rep-quant'}
 if code not in ordinary:return False
 if mode=='Numeric':return not parameter and code not in ranges and mod['min']<=mod['max']
 if mode=='DamageRange':return code in ranges and mod['min']<=mod['max']
 if mode=='Parameter':return parameter and re.fullmatch(r'[+]?\d+',str(mod['parameter'] or '')) is not None
 return False
def build(check=False):
 source=(ROOT/'src/Sanctuary.Content/ClassGear.cs').read_text();ordinary=set(re.findall(r'"([^"\n]+)"',source[source.index('_implemented ='):source.index('public static bool Implemented')]))
