 catalogue=json.loads((ROOT/'data/Sanctuary/Balance/valkyrie-affix-catalogue.json').read_text());affixes=catalogue['affixes'];filtered=[];counts=collections.Counter();ids=collections.defaultdict(set);modes=collections.defaultdict(set)
