 paths=['src/Sanctuary.Content/ClassGear.cs','src/Sanctuary.Content/NamedPropertyRuntime.cs','src/Sanctuary.Content/OrdinaryAffixProperties.cs','src/Sanctuary.Content/NamedSkills.cs','src/Sanctuary.Content/NamedGear.cs','data/Sanctuary/Balance/affixes.json','data/Sanctuary/Balance/valkyrie-affix-catalogue.json','tools/reference/named-item-runtime-audit.json']
 evidence=dict(referenceVersion='3.3.93847',scope='Source-level integration inventory. Ordinary whitelist and named registration are not proof that every stat/event/parameter or NPC consumer works.',counts=dict(ordinaryAcceptedCodes=len(ordinary),legacyAffixes=len(legacy),legacyFilteredAffixes=legacyFiltered,valkyrieTypeCompatibleAffixes=len(affixes),valkyrieAcceptedByOrdinaryFilter=len(affixes)-len(filtered),valkyrieFilteredAffixes=len(filtered),valkyrieMissingCodes=len(counts),valkyrieExistingNamedRegistrations=len(set(counts)&registered),valkyrieOutsideNamedRegistration=sorted(set(counts)-registered)),ordinaryAcceptedCodes=sorted(ordinary),valkyrieMissingProperties=entries,lastVerifiedNamedItemEffectGates={k:sorted(set(v)) for k,v in sorted(itemBlocked.items())},limits=['The current Valkyrie catalogue contains every type-compatible source affix, before rank/quality filtering. A rejected affix is not a separate missing mechanic; several rows can share one code.', 'Ordinary scalar/range/parameter properties now share the named-property interpretation while retaining legacy source IDs, numeric rolls and save layout. Player consumers still require item-specific behavioral verification; NPC equipment has no live consumer yet.', 'Named registrations for skill/skilltab remain parameter-dependent; current consumers are predominantly player-specific. NPC inheritance, weapon-local versus global stats, proc ownership and save behavior require dedicated adapters and verification.', 'Last verified named-item gates are retained as historical runtime evidence, not a fresh certificate for the in-progress working tree. Some gates reflect unimplemented class/item replacement paths or unresolved source definitions, not missing general damage systems.', 'Approved exclusions, including charms, remain intentional and must not be turned into new feature requirements.'],implementationOrder=['Verify the shared ordinary/named scalar/range/parameter resolver through real rolls, identification, equipped/broken/unequipped behavior, combat/resources, maintenance and two save/reload cycles; preserve legacy numeric saves and explicit unsupported events.', 'Implement complete source-quality affix/property rolling and actual NPC equipment stat consumers, reusing the shared combat/resource/skill systems. Do not filter out unsupported source rolls or use player-only effects as NPC proof.', 'After the relevant class mechanics are ready, return to the deferred skill-effect list: skill-event dispatch, charges, oskills/item auras and remaining newer properties, using the relevant class handlers and exact ownership/resource/target/trigger rules. Individually uncertain mechanics remain recorded while unaffected work continues.', 'Verify real ordinary magic/rare and named items plus NPC equipment through damage/resources/skills/events and two save/reload cycles. Refresh acquisition eligibility only after its consumer checks pass.'],sourceHashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in paths})
 lines=['# Item property integration gaps','', '**This gap is part of the class-mechanics work.** A supported named-item property does not automatically work on ordinary affixes or NPC equipment. This inventory describes source registration and routing; it is not a complete behavioral certificate.','',f'The ordinary generator accepts **{len(ordinary)} codes**. Of the current Valkyrie catalogue’s **{len(affixes)} type-compatible affixes**, its filter would accept **{len(affixes)-len(filtered)}** and reject **{len(filtered)}**, involving **{len(counts)} property codes**. **{len(set(counts)&registered)}** of those codes already have named-property registrations; the remaining codes are `{", ".join(sorted(set(counts)-registered))}`. Affix counts precede level and rarity filtering.','', 'Ordinary leech, elemental/poison ranges, regeneration, damage reduction, level-scaled stats, requirements and maintenance now use the shared property representation. Skill grants/events and socket affixes remain gated. The table below lists the exact remaining ordinary-route gaps; complete NPC property application remains separate work.','', 'The broader named-item backlog also contains skill procs, charged skills, oskills, item-granted auras, reanimation, Magic Arrow/Exploding Arrow item replacements, and newer immunity-breaking/Sunder property groups. Some direct-skill gates are waiting for their class handlers; some newer source definitions are unresolved. See [named-item readiness](named-item-readiness.md) and the machine inventory’s recorded gate codes.','', 'Valkyrie additionally needs NPC consumers for the selected equipment. Existing player stat/effect code is a reuse point, not a substitute for source-appropriate summon behavior. Charms remain intentionally excluded by Sanctuary policy.','', '## Implementation order','']
 lines += [f'{i}. {text}' for i,text in enumerate(evidence['implementationOrder'],1)]
 evidence['recipientNumericContext']=dict(status='Prepared numeric suppliers; full NPC stat graph/combat remains unfinished',receipt='tools/reference/npc-item-suppliers-native-evidence.json',sourceReceipt='tools/reference/npc-item-suppliers-source-evidence.json',explicitRecipientLevel=True,resourceFractionUnits='FP256',halfScaledToHitProperties=['att/lvl','att%/lvl','att-dem/lvl','att-und/lvl'])
